int target_pidfd = 3;
size_t size = 4096;
void *addr = (void*)0x7f0000000000;

struct iovec ranges[1] = {
    {
        .iov_base = addr,
        .iov_len = size
    }
};

// Advice types: MADV_DONTNEED, MADV_COLD, MADV_PAGEOUT, etc.
int advice = MADV_DONTNEED;

long ret = process_madvise(
    target_pidfd,
    ranges,
    1,              // vlen (number of vectors)
    advice,
    0               // flags (currently 0)
);

if (ret == -1) {
    // Handle error (errno set)
}
